import{Z as t,e as o,f as i,a0 as n}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"HubSpot","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/hubspot.md","filePath":"integrations/crm/hubspot.md","lastUpdated":1781302918000}'),r={name:"integrations/crm/hubspot.md"};function s(a,e,c,l,h,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="hubspot" tabindex="-1">HubSpot <a class="header-anchor" href="#hubspot" aria-label="Permalink to &quot;HubSpot&quot;">​</a></h1><p>Connect HubSpot to send enquiries to the records your team manages. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select HubSpot as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-hubspot-api" tabindex="-1">Step 2. Connect to the HubSpot API <a class="header-anchor" href="#step-2-connect-to-the-hubspot-api" aria-label="Permalink to &quot;Step 2. Connect to the HubSpot API&quot;">​</a></h3><ol><li>Go to <a href="https://www.hubspot.com/" target="_blank">HubSpot</a> and login to your account.</li><li>Click on the settings icon on the top-right of the screen.</li><li>In the left-hand sidebar menu, click on <strong>Integrations</strong> → <strong>Private Apps</strong>.</li><li>Click the <strong>Create a private app</strong> button.</li><li>Fill out the details, and click the <strong>Scopes</strong> tab. Select the following scopes: <ul><li><code>crm.lists.read</code></li><li><code>crm.objects.companies.read</code></li><li><code>crm.objects.companies.write</code></li><li><code>crm.objects.contacts.read</code></li><li><code>crm.objects.contacts.write</code></li><li><code>crm.objects.deals.read</code></li><li><code>crm.objects.deals.write</code></li><li><code>crm.schemas.custom.read</code></li><li><code>tickets</code></li><li><code>forms</code></li></ul></li><li>Click the <strong>Create App</strong> button in the top right.</li><li>In the dialog box, review the info about your app&#39;s access token, then click <strong>Continue creating</strong>.</li><li>Copy the <strong>Access Token</strong> from HubSpot and paste in the <strong>Access Token</strong> field in Formie.</li></ol><h3 id="step-3-disable-automatic-form-collection" tabindex="-1">Step 3. Disable Automatic Form Collection <a class="header-anchor" href="#step-3-disable-automatic-form-collection" aria-label="Permalink to &quot;Step 3. Disable Automatic Form Collection&quot;">​</a></h3><ol><li>In HubSpot, click on the <strong>Settings</strong> cog icon in the top right-hand of the screen.</li><li>In the left-hand sidebar menu, click on <strong>Marketing</strong> → <strong>Forms</strong>.</li><li>Click the <strong>Non-Hubspot Forms</strong> button.</li><li>For <strong>Collect data from website forms</strong> ensure that this is switched to <strong>Off</strong>.</li></ol><h3 id="step-4-test-connection" tabindex="-1">Step 4. Test Connection <a class="header-anchor" href="#step-4-test-connection" aria-label="Permalink to &quot;Step 4. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-5-form-setting" tabindex="-1">Step 5. Form Setting <a class="header-anchor" href="#step-5-form-setting" aria-label="Permalink to &quot;Step 5. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the record types this integration exposes, then map the required destination fields using the variable picker. For a contact enquiry, map the visitor’s email and name where those fields are available. Use the requirements shown for your selected record type rather than assuming every CRM accepts the same fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="custom-objects-enterprise" tabindex="-1">Custom Objects (Enterprise) <a class="header-anchor" href="#custom-objects-enterprise" aria-label="Permalink to &quot;Custom Objects (Enterprise)&quot;">​</a></h3><p>When using <strong>Map to Form</strong> with HubSpot custom object properties, Formie fetches your portal’s custom object schemas when you refresh HubSpot forms. Form fields are mapped using the correct <code>objectTypeId</code> (for example <code>2-21479350</code>) automatically.</p><p>Ensure your private app includes the <code>crm.schemas.custom.read</code> scope, and refresh HubSpot forms after creating or changing custom objects in HubSpot.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the test record in the selected CRM destination. Check the mapped values and whether the integration created a record or updated an existing one as intended.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',18)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
